  'step4-text' => 'चरण 4: टेक्स्ट छवियों और लेआउट गुणवत्ता की जांच करने के लिए संपीड़ित दस्तावेज़ का पूर्वावलोकन करें।',
  'step5-text' => 'चरण 5: यदि गुणवत्ता पढ़ने की अपेक्षाओं के अनुरूप नहीं है तो संपीड़न सेटिंग्स समायोजित करें।',
  'step6-text' => 'चरण 6: पूर्वावलोकन सामग्री और स्पष्टता आवश्यकताओं को पूरा करने के बाद प्रक्रिया को अंतिम रूप दें।',
  'step7-text' => 'चरण 7: अनुकूलित पीडीएफ फ़ाइल डाउनलोड करें और इसे साझा करने के लिए सुरक्षित रूप से संग्रहीत करें।',
  'free-vs-paid-heading' => 'निःशुल्क बनाम सशुल्क पीडीएफ संपीड़न उपकरण',
  'comparison-feature' => 'विशेषता',
  'comparison-free' => 'निःशुल्क पीडीएफ संपीड़न उपकरण',
